INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','restaurante','Restaurante Tribeca','Alta cocina de pescados y mariscos en el barrio de Los Remedios: carrillada de atún, ostras, bogavante, yema de huevo con trufa; tratamiento inteligente de temperatura y textura en cada preparación','gastronomia_ampliacion');
