INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','restaurante','Espacio Eslava','Gastrobar referente de Sevilla con 7.500 reseñas: tapas modernas y tradicionales de altísimo nivel, servicio excepcional y precios contenidos; reserva imprescindible en barrio de San Lorenzo','gastronomia_ampliacion');
