INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','restaurante','El Pasaje Tapas','Tapas creativas con producto premium: alcachofa rellena con embutidos ibéricos y beurre blanc, tartar de atún con helado de wasabi, ventresca de atún rojo a la plancha; más de 9.600 reseñas','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','restaurante','Vineria San Telmo','Vinoteca y gastrobar junto al parque de María Luisa: espaguetis de tinta de calamar, rabo de toro, ceviche, carpaccio ibérico y tarta de queso; carta de vinos muy cuidada; 3.700 reseñas','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','restaurante','Bar Alfalfa','Bar mítico del Casco Antiguo: jamón ibérico, paella de mariscos, pulpo a la plancha y ensalada con piñones y nueces; ambiente auténtico y animado; más de 7.800 reseñas','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','restaurante','Ovejas Negras Tapas','Tapas modernas en el centro histórico: croquetas caseras, risotto de setas, alitas crujientes, lomo ibérico a la plancha y picanha carpaccio; vino de barril y cerveza artesana; 6.250 reseñas','gastronomia_ampliacion');
