INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','restaurante','Tradevo Centro','Recomendado por la Guía Michelin: anchovitas frescas, sardinas, gambas delicadas, tataki de atún rojo, chipirones fritos y ceviche; producto del mar tratado con técnica y respeto; 2.135 reseñas','gastronomia_ampliacion');
