INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90966','restaurante','Restaurante Casa Calvillo','Bar-restaurante en plaza con noria. Plato estrella: mollete con serrano y menú del día a precio honesto','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90967','restaurante','La Tasca de José','Tasca de cocina de montaña. Plato estrella: morcilla de la zona, carrillera en salsa de castañas y oreja ibérica','gastronomia_ampliacion');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90967','restaurante','Bar Restaurante El Pantano','Bar de carretera con vistas al embalse. Plato estrella: desayuno serrano y menú del día económico','gastronomia_ampliacion');

